import XCTest

final class TapHarnessUITests: XCTestCase {
    func testDismissDialog() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        let gotIt = app.buttons["Got it"].firstMatch
        if gotIt.waitForExistence(timeout: 10) {
            gotIt.tap()
        }
        Thread.sleep(forTimeInterval: 2)
    }
}

import XCTest

final class TapHarnessUITests: XCTestCase {
    func testOpenRoomInfo() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        let navTitle = app.navigationBars.firstMatch.staticTexts["Team Standup"].firstMatch
        if navTitle.waitForExistence(timeout: 10) {
            navTitle.tap()
        } else {
            app.staticTexts["Team Standup"].firstMatch.tap()
        }
        Thread.sleep(forTimeInterval: 3)
    }
}

