import XCTest

final class TapHarnessUITests: XCTestCase {
    func testOpenRoomInfo() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        Thread.sleep(forTimeInterval: 1)

        let closeBtn = app.buttons["Close"].firstMatch
        if closeBtn.exists {
            closeBtn.tap()
        } else {
            app.coordinate(withNormalizedOffset: CGVector(dx: 362.0 / 393.0, dy: 523.0 / 852.0)).tap()
        }
        Thread.sleep(forTimeInterval: 1)

        let nav = app.navigationBars.firstMatch
        nav.coordinate(withNormalizedOffset: CGVector(dx: 150.0 / 393.0, dy: 0.5)).tap()
        Thread.sleep(forTimeInterval: 3)
    }
}
